import 'package:flutter/material.dart';
import '../services/risk_engine.dart';
class RiskGuardianScreen extends StatefulWidget{const RiskGuardianScreen({super.key});@override State<RiskGuardianScreen> createState()=>_RiskGuardianState();}
class _RiskGuardianState extends State<RiskGuardianScreen>{double balance=1000,risk=1,daily=-12,limit=3,openRisk=14,maxOpen=50,rr=2,minRr=2;@override Widget build(BuildContext c){final g=RiskEngine.guardian(balance:balance,riskPercent:risk,dailyPnl:daily,dailyLimitPercent:limit,openRisk:openRisk,maxOpenRisk:maxOpen,rr:rr,minRr:minRr,highImpactNews:false);return Scaffold(appBar:AppBar(title:const Text('RISK GUARDIAN')),body:ListView(padding:const EdgeInsets.all(16),children:[Text('TRADE CHECK',style:Theme.of(c).textTheme.headlineSmall),const SizedBox(height:16),_row('Balance',r'$'+balance.toStringAsFixed(2),true),_row('Risk / trade',risk.toStringAsFixed(2)+'%',true),_row('Daily loss limit',limit.toStringAsFixed(1)+'%',g['dailyOk']),_row('Open risk',r'$'+openRisk.toStringAsFixed(2),g['openRiskOk']),_row('R:R', '1:'+rr.toStringAsFixed(1),g['rrOk']),const SizedBox(height:20),Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:g['ready']==true?Colors.green.withOpacity(.12):Colors.red.withOpacity(.12),borderRadius:BorderRadius.circular(16)),child:Text(g['ready']==true?'🟢 TRADE PLAN READY':'🔴 ENTRY BLOCKED',style:TextStyle(fontWeight:FontWeight.w900,color:g['ready']==true?Colors.greenAccent:Colors.redAccent))) ]));}Widget _row(String a,String b,bool ok)=>ListTile(title:Text(a),trailing:Text((ok?'✅ ':'⚠️ ')+b));}
